"""Contact sheet for substitute teachers."""

from rosterkit.errors import ProjectError

# ---
def contact_rows(students):
    """Text rows of name, section and email, by name."""
    if not students:
        raise ProjectError("no students for the sheet")
    ordered = sorted(students, key=_name)
    cells = [_cells(stud) for stud in ordered]
    widths = [max(map(len, col)) for col in zip(*cells)]
    return [_line(row, widths) for row in cells]

def _name(stud):
    return stud.display_name

def _cells(stud):
    if not stud.email:
        raise ProjectError(f"no email: {_name(stud)}")
    return (stud.display_name, stud.section, stud.email)

def _line(row, widths):
    pairs = zip(row, widths)
    padded = [cell.ljust(wide) for cell, wide in pairs]
    return "  ".join(padded).rstrip()

